/**
 * Favicon pipeline.
 *
 * Derives browser and app icons from the transparent Dealup mark generated by
 * `npm run build:logo`. The favicon keeps transparency for browser tabs, while
 * app/manifest icons sit on the site's soft background for a cleaner installed
 * app tile.
 *
 * Re-run after replacing the source logo: npm run build:favicon
 */
import { mkdir, writeFile } from "node:fs/promises";
import sharp from "sharp";

const SRC = "public/assets/logos/dealup-mark.png";
const APP_OUT = "src/app";
const PUBLIC_OUT = "public/icons";
const BACKGROUND = "#fafcfb";

async function squarePng(size, { background = null, padding = 0.1 } = {}) {
  const image = sharp(SRC).ensureAlpha();
  const meta = await image.metadata();
  const inset = Math.round(size * padding);
  const maxWidth = size - inset * 2;
  const maxHeight = size - inset * 2;

  const resized = await image
    .resize({
      width: maxWidth,
      height: maxHeight,
      fit: "inside",
      withoutEnlargement: false,
    })
    .png()
    .toBuffer();
  const resizedMeta = await sharp(resized).metadata();

  const base = sharp({
    create: {
      width: size,
      height: size,
      channels: 4,
      background: background ?? { r: 0, g: 0, b: 0, alpha: 0 },
    },
  });

  const density = meta.density ?? 72;
  return base
    .composite([
      {
        input: resized,
        left: Math.round((size - resizedMeta.width) / 2),
        top: Math.round((size - resizedMeta.height) / 2),
      },
    ])
    .png({ compressionLevel: 9 })
    .withMetadata({ density })
    .toBuffer();
}

function icoFromPngs(images) {
  const headerSize = 6;
  const entrySize = 16;
  let offset = headerSize + images.length * entrySize;

  const header = Buffer.alloc(headerSize);
  header.writeUInt16LE(0, 0);
  header.writeUInt16LE(1, 2);
  header.writeUInt16LE(images.length, 4);

  const entries = [];
  for (const image of images) {
    const entry = Buffer.alloc(entrySize);
    entry.writeUInt8(image.size === 256 ? 0 : image.size, 0);
    entry.writeUInt8(image.size === 256 ? 0 : image.size, 1);
    entry.writeUInt8(0, 2);
    entry.writeUInt8(0, 3);
    entry.writeUInt16LE(1, 4);
    entry.writeUInt16LE(32, 6);
    entry.writeUInt32LE(image.buffer.length, 8);
    entry.writeUInt32LE(offset, 12);
    entries.push(entry);
    offset += image.buffer.length;
  }

  return Buffer.concat([header, ...entries, ...images.map((image) => image.buffer)]);
}

await mkdir(PUBLIC_OUT, { recursive: true });

const faviconSizes = [16, 32, 48];
const faviconFrames = await Promise.all(
  faviconSizes.map(async (size) => ({
    size,
    buffer: await squarePng(size, { padding: 0.06 }),
  }))
);

await writeFile(`${APP_OUT}/favicon.ico`, icoFromPngs(faviconFrames));
await writeFile(`${APP_OUT}/icon.png`, await squarePng(512, { padding: 0.09 }));
await writeFile(`${APP_OUT}/apple-icon.png`, await squarePng(180, { background: BACKGROUND, padding: 0.12 }));
await writeFile(`${PUBLIC_OUT}/dealup-icon-192.png`, await squarePng(192, { background: BACKGROUND, padding: 0.12 }));
await writeFile(`${PUBLIC_OUT}/dealup-icon-512.png`, await squarePng(512, { background: BACKGROUND, padding: 0.12 }));

console.log(`favicon.ico         ${faviconSizes.join(", ")}px`);
console.log("icon.png            512px");
console.log("apple-icon.png      180px");
console.log("dealup-icon-192.png 192px");
console.log("dealup-icon-512.png 512px");
